V.houses=()=>mobilePage('我的房屋',`${App.state.addresses.map(ad=>`<a href="#/house?id=${ad.id}" class="card mb16" style="display:block"><div class="flex gap12"><span class="category-icon">${icon('home',26)}</span><div><h3 style="font-size:15px">${e(ad.community)}</h3><p style="font-size:11px;margin-top:5px">${e(ad.area||'待填写')}㎡ · ${e(ad.year||'待填写')}年建成</p></div></div><div class="between mt16">${badge('档案已建立','green')}<span class="text-link">查看房屋档案${icon('arrow',14)}</span></div></a>`).join('')}${linkBtn('添加房屋信息','address-edit','secondary full')}`);
V.house=()=>{const ad=App.state.addresses.find(a=>a.id===App.query.get('id'))||App.state.addresses[0];return mobilePage('房屋档案',`${card(`<div class="flex gap12"><span class="category-icon">${icon('home',30)}</span><div><h2>${e(ad?.community||'我的房屋')}</h2><p style="font-size:11px;margin-top:5px">${e(ad?.area||'98')}㎡ · 住宅</p></div></div>${row('地址信息',e(ad?.detail||'待填写'))}${row('建成年份',e(ad?.year||'待填写'))}`)}${section('设备台账',card(`${row('厨房给水系统','待补充设备资料','','water')}${row('家用空调','已有关联清洗记录','','air')}${row('入户门锁','已有关联更换记录','','door')}`))}${section('维修记录',completed().map(o=>`<a class="card mb16" style="display:block" href="#/report?id=${o.id}">${orderSummary(o)}</a>`).join(''))}${notice('房屋健康评分和预测维保待后续接入真实设备数据，不根据空档案生成健康结论。')}`);};
V.membership=()=>{const level=App.query.get('level')||'黄金',plans={'免费':[0,'基础报修与标准质保'],'白银':[299,'每年2次检测 · 人工9折'],'黄金':[599,'年度水电体检 · 人工85折'],'钻石':[999,'专属管家 · 人工8折']};return mobilePage('会员中心',`<div class="chips mb16">${Object.keys(plans).map(l=>`<a class="chip ${level===l?'active':''}" href="#/membership?level=${l}">${l}会员</a>`).join('')}</div><div class="membership-card">${icon('medal',34)}<h2 class="mt16">${e(level)}家庭管家</h2><p>${plans[level]?.[1]||plans['黄金'][1]}</p><div class="amount">${yuan(plans[level]?.[0]||0)}<small style="color:#c5b39d;font-size:13px;font-weight:400"> / 年</small></div><p>原始会员方案展示，尚未开通售卖</p></div>${section('原方案权益',card(`${row('优先派单','按所选等级方案')}${row('年度检测','以正式会员条款为准')}${row('维修与材料折扣','仅在平台确认范围内适用')}${row('质保延长','以正式服务协议为准')}`))}${notice('年费和权益取自093会员方案，235将会员列为后续迭代。本页面不创建付费会员交易。','orange')}<div class="stack mt16">${linkBtn('查看房屋档案','houses','secondary full')}${linkBtn('积分与权益','points','secondary full')}</div>`);};
