V.discover=()=>{const tab=App.query.get('tab')||'knowledge';return mobilePage('家居发现',`${filterTabs([['knowledge','维保知识'],['cases','局改案例'],['goods','优选商品']],tab,'tab')}${tab==='knowledge'?card(`<details class="details" open><summary>水龙头滴水，先检查什么？</summary><p>先关闭对应进水阀并观察漏水位置，记录使用年限与具体情况，安排师傅检测。切勿自行拆卸带压管件。</p></details><details class="details"><summary>空调换季前的清洁检查</summary><p>记录空调型号、使用频率与异常情况，按照产品说明安排清洁与专业检修。</p></details><details class="details"><summary>维修记录为什么要保留？</summary><p>完整的故障描述、报价与照片有助于后续质保追溯和维护计划。</p></details>`):empty(tab==='cases'?'案例内容待运营上架':'优选商品待供应链配置','保留原始需求中的栏目，当前没有已审核发布的实际内容。','','')}`);};

// Four approved primary categories; secondary groups and project cards share the same data.
V.categories=()=>{
 const tree=ZHZ_USER_CATEGORY_TREE,selected=App.query.get('category');
 const category=tree.find(c=>c.name===selected||c.groups.includes(selected))||tree[0];
 const requested=App.query.get('sub')|| (category.groups.includes(selected)?selected:'all');
 const sub=category.groups.includes(requested)?requested:'all';
 const items=visibleCatalog().filter(item=>item.categoryId===category.id);
 return mobilePage('全部服务',`<div class="category-search">${mobileSearch()}</div><div class="category-layout"><nav class="category-sidebar" aria-label="服务分类">${tree.map(c=>`<button class="${category.id===c.id?'active':''}" ${category.id===c.id?'aria-current="true"':''} data-action="category-select" data-category="${e(c.name)}">${e(c.name)}</button>`).join('')}</nav><div class="category-content"><h2>${e(category.name)}</h2><nav class="catalog-subnav" aria-label="二级分类">${['all',...category.groups].map(group=>`<a class="${group===sub?'active':''}" ${group===sub?'aria-current="true"':''} href="#/categories?category=${encodeURIComponent(category.name)}&sub=${encodeURIComponent(group)}">${e(group==='all'?'全部':group)}</a>`).join('')}</nav>${category.groups.filter(g=>sub==='all'||g===sub).map(group=>`<section class="phase1-catalog-group"><h3>${e(group)}</h3><div class="catalog-grid source-service-grid">${items.filter(item=>item.group===group).map(catalogTile).join('')}</div></section>`).join('')}</div></div><a class="category-support" href="#/chat?support=1"><span>没找到需要的服务？</span><strong>联系客服${icon('arrow',13)}</strong></a>`,'','categories',{edge:true});
};
App.afterRender=()=>{
 if(App.route==='categories'){const rail=document.querySelector('.category-sidebar'),selected=rail?.querySelector('button.active');if(rail&&selected){const top=selected.offsetTop-rail.offsetTop;rail.scrollTop=top+selected.offsetHeight>rail.clientHeight?Math.max(0,top-rail.clientHeight/2):0;}}
 if(App.temp.paymentTimer){clearInterval(App.temp.paymentTimer);App.temp.paymentTimer=null;}
 if(App.route==='payment'){
  const update=()=>{const el=document.getElementById('payment-countdown');if(!el)return;const remain=Math.max(0,Math.ceil((App.temp.paymentDeadline-Date.now())/1000));el.textContent=`${String(Math.floor(remain/60)).padStart(2,'0')}:${String(remain%60).padStart(2,'0')}`;if(remain===0){const o=current();if(o.status==='pending'){App.updateOrder(o.id,{status:'cancelled'},'15分钟未支付，订单关闭');App.go('order',{id:o.id});toast('订单支付超时，已关闭');}}};update();App.temp.paymentTimer=setInterval(update,1000);
 }
};
App.render();
